const listAnnouncementsUsingTemplate = `-- name: ListAnnouncementsUsingTemplate :many
SELECT id FROM signage_announcements WHERE template_id = $1 AND (ends_at IS NULL OR ends_at > $2::timestamptz) ORDER BY starts_at, id
`

type ListAnnouncementsUsingTemplateParams struct {
	TemplateID uuid.UUID
	Now        time.Time
}

func (q *Queries) ListAnnouncementsUsingTemplate(ctx context.Context, arg ListAnnouncementsUsingTemplateParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listAnnouncementsUsingTemplate, arg.TemplateID, arg.Now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

